use atlas_joined_probe::{Source,build_sources};
use atlas_llama_probe::Encoder;
use std::time::Instant;
#[test] fn pilot(){let dir=std::env::temp_dir().join(format!("atlas-pilot-{}",std::process::id()));let model=Encoder::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();let mut bodies:Vec<_>=(0..10).map(|i|format!("Документ номер {i}. {}", "Помидоры нужно поливать по утрам и беречь от заморозков. ".repeat(16))).collect();let ids:Vec<_>=(0..10).map(|i|i.to_string()).collect();let sources:Vec<_>=ids.iter().zip(&bodies).map(|(id,body)|Source{id,title:"Огород",body,description:""}).collect();let t=Instant::now();build_sources(&model,&sources,&dir).unwrap();let first=t.elapsed().as_secs_f64();bodies[0].push_str(" Изменённая строка.");let sources:Vec<_>=ids.iter().zip(&bodies).map(|(id,body)|Source{id,title:"Огород",body,description:""}).collect();let t=Instant::now();build_sources(&model,&sources,&dir).unwrap();eprintln!("pilot: documents=10, initial={first:.2}s, single_edit={:.2}s",t.elapsed().as_secs_f64());std::fs::remove_dir_all(dir).unwrap();}
